"""Generic Rust helpers (``mod rt``) embedded in exported programs: elements, links, ghost pads."""

RT = r"""
/// Generic helpers generated by Pipelab: elements, links and ghost pads.
mod rt {
    use super::*;
    use std::collections::BTreeMap;

    pub type Elements = BTreeMap<String, gst::Element>;

    /// Creates an element, sets its properties (parsed like gst-launch) and adds it.
    pub fn make_element(
        container: &gst::Bin,
        factory: &str,
        name: &str,
        properties: &[(&str, &str)],
    ) -> Result<gst::Element> {
        let mut builder = gst::ElementFactory::make(factory).name(name);
        for (key, value) in properties {
            builder = builder.property_from_str(key, value);
        }
        let element =
            builder.build().with_context(|| format!("element '{factory}' is not installed"))?;
        container.add(&element)?;
        Ok(element)
    }

    /// An existing pad, or a newly requested one.
    pub fn pad_of(element: &gst::Element, name: &str) -> Result<gst::Pad> {
        element
            .static_pad(name)
            .or_else(|| element.request_pad_simple(name))
            .ok_or_else(|| anyhow!("{} has no pad {name}", element.name()))
    }

    fn get<'a>(elements: &'a Elements, name: &str) -> Result<&'a gst::Element> {
        elements.get(name).ok_or_else(|| anyhow!("no element {name}"))
    }

    /// `name`, or `instance/inner` for elements inside component instances.
    pub fn find_element(
        pipeline: &gst::Pipeline,
        elements: &Elements,
        path: &str,
    ) -> Result<gst::Element> {
        let mut parts = path.split('/');
        let first = parts.next().unwrap_or_default();
        let found = elements.get(first).cloned().or_else(|| pipeline.by_name(first));
        let mut element = found.ok_or_else(|| anyhow!("no element {path}"))?;
        for part in parts {
            let bin = element
                .downcast::<gst::Bin>()
                .map_err(|_| anyhow!("{path}: not a bin before {part}"))?;
            element = bin.by_name(part).ok_or_else(|| anyhow!("no element {path}"))?;
        }
        Ok(element)
    }

    pub fn configure_pad(
        element: &gst::Element,
        pad: &str,
        properties: &[(&str, &str)],
    ) -> Result<()> {
        let pad = pad_of(element, pad)?;
        for (key, value) in properties {
            pad.set_property_from_str(key, value);
        }
        Ok(())
    }

    pub fn link(
        elements: &Elements,
        src: &str,
        src_pad: &str,
        sink: &str,
        sink_pad: &str,
    ) -> Result<()> {
        let source = pad_of(get(elements, src)?, src_pad)?;
        let target = pad_of(get(elements, sink)?, sink_pad)?;
        source
            .link(&target)
            .with_context(|| format!("could not link {src}.{src_pad} to {sink}.{sink_pad}"))?;
        Ok(())
    }

    fn matches(pad: &gst::Pad, name: &str) -> bool {
        pad.name() == name || pad.pad_template().is_some_and(|t| t.name_template() == name)
    }

    /// Links a *sometimes* pad (name or template `src_pad`) once it appears.
    pub fn link_dynamic(
        elements: &Elements,
        src: &str,
        src_pad: &str,
        sink: &str,
        sink_pad: &str,
    ) -> Result<()> {
        let target = pad_of(get(elements, sink)?, sink_pad)?;
        let wanted = src_pad.to_string();
        get(elements, src)?.connect_pad_added(move |element, pad| {
            if !matches(pad, &wanted)
                || target.is_linked()
                || !pad.query_caps(None).can_intersect(&target.query_caps(None))
            {
                return;
            }
            if let Err(err) = pad.link(&target) {
                eprintln!("could not link {}.{}: {err:?}", element.name(), pad.name());
            }
        });
        Ok(())
    }

    /// Sets a property from its text like gst-launch; GstPad-typed properties take a pad name.
    pub fn apply_value(
        element: &gst::Element,
        property: &str,
        text: &str,
        pad: Option<&str>,
    ) -> Result<()> {
        let target: gst::Object = match pad {
            Some(name) => pad_of(element, name)?.upcast(),
            None => element.clone().upcast(),
        };
        let pspec = target
            .find_property(property)
            .ok_or_else(|| anyhow!("{} has no property {property}", target.name()))?;
        if pspec.value_type().is_a(gst::Pad::static_type()) {
            let pad = element
                .static_pad(text)
                .ok_or_else(|| anyhow!("{} has no pad {text}", element.name()))?;
            target.set_property(property, &pad);
        } else {
            target.set_property_from_str(property, text);
        }
        Ok(())
    }

    fn ghost(container: &gst::Bin, inner: &gst::Pad, port: &str) -> Result<()> {
        let proxy = gst::GhostPad::builder_with_target(inner)?.name(port).build();
        if container.current_state() != gst::State::Null {
            proxy.set_active(true)?;
        }
        container.add_pad(&proxy)?;
        Ok(())
    }

    /// Ghost pad named `port` on `container` for an inner pad (added later for sometimes pads).
    pub fn expose_port(
        container: &gst::Bin,
        element: &gst::Element,
        pad: &str,
        port: &str,
        presence: &str,
    ) -> Result<()> {
        if presence != "sometimes" {
            return ghost(container, &pad_of(element, pad)?, port);
        }
        let bin = container.downgrade();
        let (wanted, port) = (pad.to_string(), port.to_string());
        element.connect_pad_added(move |_, inner| {
            let Some(bin) = bin.upgrade() else { return };
            if matches(inner, &wanted) && bin.static_pad(&port).is_none() {
                if let Err(err) = ghost(&bin, inner, &port) {
                    eprintln!("could not expose {port}: {err:#}");
                }
            }
        });
        Ok(())
    }
}
"""

PIPELINE = """
type MessageCallback = Arc<dyn Fn(&gst::Message) + Send + Sync>;

struct Inner {
    pipeline: gst::Pipeline,
    elements: Elements,
    callbacks: Mutex<Vec<MessageCallback>>,
    watch: Mutex<Option<gst::bus::BusWatchGuard>>,
    main_loop: Mutex<Option<glib::MainLoop>>,
    error: Mutex<Option<String>>,
}

/// NAME: owns the pipeline, its elements and the bus handling (cheap to clone).
#[derive(Clone)]
pub struct PIPELINE {
    inner: Arc<Inner>,
}

impl PIPELINE {
    /// The underlying GstPipeline.
    pub fn pipeline(&self) -> &gst::Pipeline {
        &self.inner.pipeline
    }

    /// An element by name, or `instance/inner` inside component instances.
    pub fn element(&self, path: &str) -> Result<gst::Element> {
        rt::find_element(&self.inner.pipeline, &self.inner.elements, path)
    }

    /// Sets the pipeline to PLAYING; the default GLib main context must run (see `run()`).
    pub fn start(&self) -> Result<()> {
        let mut watch = self.inner.watch.lock().unwrap();
        if watch.is_none() {
            let weak = Arc::downgrade(&self.inner);
            let bus = self.inner.pipeline.bus().context("the pipeline has no bus")?;
            *watch = Some(bus.add_watch(move |_, message| {
                if let Some(inner) = weak.upgrade() {
                    PIPELINE { inner }.on_bus(message);
                }
                glib::ControlFlow::Continue
            })?);
        }
        drop(watch);
        self.inner.pipeline.set_state(gst::State::Playing).context("the pipeline refused to start")?;
        Ok(())
    }

    pub fn stop(&self) -> Result<()> {
        self.inner.pipeline.set_state(gst::State::Null)?;
        self.inner.watch.lock().unwrap().take();
        Ok(())
    }

    /// Asks the sources to finish so muxers and files are finalised cleanly.
    pub fn send_eos(&self) {
        self.inner.pipeline.send_event(gst::event::Eos::new());
    }

    /// `callback` receives every bus message, before the default handling.
    pub fn connect_message<F: Fn(&gst::Message) + Send + Sync + 'static>(&self, callback: F) {
        self.inner.callbacks.lock().unwrap().push(Arc::new(callback));
    }

    /// Plays until end-of-stream or an error (call `send_eos()` to finish early).
    pub fn run(&self) -> Result<()> {
        let main_loop = glib::MainLoop::new(None, false);
        *self.inner.main_loop.lock().unwrap() = Some(main_loop.clone());
        self.start()?;
        main_loop.run();
        self.stop()?;
        match self.inner.error.lock().unwrap().take() {
            Some(error) => Err(anyhow!(error)),
            None => Ok(()),
        }
    }

    fn on_bus(&self, message: &gst::Message) {
        use gst::MessageView;
        let callbacks = self.inner.callbacks.lock().unwrap().clone();
        for callback in callbacks {
            callback(message);
        }
        let source = || message.src().map(|s| s.path_string().to_string()).unwrap_or_default();
        match message.view() {
            MessageView::Error(error) => {
                let text = format!("{}: {} ({:?})", source(), error.error(), error.debug());
                eprintln!("ERROR from {text}");
                *self.inner.error.lock().unwrap() = Some(text);
                self.quit();
            }
            MessageView::Warning(warning) => eprintln!("WARNING from {}: {}", source(), warning.error()),
            MessageView::Eos(_) => self.quit(),
            _ => {}
        }
    }

    fn quit(&self) {
        if let Some(main_loop) = self.inner.main_loop.lock().unwrap().as_ref() {
            main_loop.quit();
        }
    }
}
"""
